// Declaraciones de módulos de imagen para suprimir advertencias del IDE
// cuando se importan assets con require() en TypeScript.
declare module '*.png' {
  const value: number;
  export default value;
}
declare module '*.jpg' {
  const value: number;
  export default value;
}
declare module '*.jpeg' {
  const value: number;
  export default value;
}
declare module '*.svg' {
  const value: number;
  export default value;
}
declare module '*.webp' {
  const value: number;
  export default value;
}
